void Monstey_Put(Monstey_Image &im,Monstey_U64 a,Monstey_U64 v,std::size_t n=8){for(std::size_t i=0;i<n;++i)im.at(static_cast<std::size_t>(a)+i)=static_cast<std::uint8_t>(v>>(8*i));}
